DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.pm_billing_register_issued(uuid[],text,date)'::regprocedure) INTO d;d:=replace(d,'doc:=public.fin_register_issued_document(', 'FOR p IN SELECT * FROM pm_payment_schedule_items WHERE id=ANY(_items) LOOP PERFORM public.fin_mark_incoming_issued(p.id,_number,_date);END LOOP; doc:=public.fin_register_issued_document(');d:=replace(d,'lines); FOR p IN SELECT * FROM pm_payment_schedule_items WHERE id=ANY(_items) LOOP PERFORM public.fin_mark_incoming_issued(p.id,_number,_date);END LOOP;RETURN doc;','lines);RETURN doc;');EXECUTE d;END $$;